SourceCode.Declaration:
/// <summary>
/// "Extensions in code" panel: Chain of Command wrappers, event handlers and extension classes that
/// target the selected class, table, view, data entity, form or query. Reads <c>ARBCodeExtensions</c>, filled
/// by <c>ARBCodeExtensionPopulateService</c>.
/// </summary>
[ARBAOTDetailPanelAttribute(ARBAOTDetailPanel::Extensions)]
class ARBAOTDetailPanelExtensionsProvider extends ARBAOTDetailPanelProvider
{
}

Method.Source:
public boolean supports(ARBAOTObjectType _objectType)
{
    switch (_objectType)
    {
        case ARBAOTObjectType::Class:
        case ARBAOTObjectType::Table:
        case ARBAOTObjectType::View:
        case ARBAOTObjectType::DataEntity:
        case ARBAOTObjectType::Form:
        case ARBAOTObjectType::Query:
            return true;
    }

    return false;
}

protected void populate(ARBAOTObjectType _objectType, TreeNodeName _objectName, anytype _aotObject)
{
    ARBCodeExtensions codeExtensions;

    select firstonly RecId from codeExtensions
        where codeExtensions.RecId != 0;

    if (!codeExtensions.RecId)
    {
        this.addLine('', "@AOTBrowser:CodeExtensionsNotPopulated");
        return;
    }

    while select codeExtensions
        order by Kind, ExtensionClass, Method
        where codeExtensions.TargetName == _objectName
           && codeExtensions.TargetType == _objectType
    {
        this.addLine(
            enum2Str(codeExtensions.Kind),
            codeExtensions.ExtensionClass,
            codeExtensions.Method,
            codeExtensions.EventType,
            codeExtensions.NestedTarget,
            codeExtensions.Package,
            ARBAOTObjectType::Class,
            codeExtensions.ExtensionClass);
    }
}
